* { box-sizing: border-box; }
:root { font-family: system-ui, sans-serif; color: #263238; background: #f5f0e6; }
body { min-width: 360px; min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; }
.card { width: min(100%, 480px); padding: 30px; border: 1px solid #e2d9c9; border-radius: 24px; background: #fffdf8; box-shadow: 0 18px 50px #4a39201c; }
header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #8b6955; font-size: 16px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(28px, 8vw, 38px); line-height: 1.1; }
.intro { margin: 12px auto 24px; max-width: 340px; color: #59666a; font-size: 17px; line-height: 1.5; }
.game { padding: 20px; border-radius: 18px; background: #f5f0e6; }
.status-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; font-size: 17px; }
.status-row strong { min-width: 42px; padding: 5px 12px; border-radius: 999px; background: #fffdf8; text-align: center; }
.board { display: grid; grid-template-columns: repeat(6, 1fr); gap: 7px; width: 100%; aspect-ratio: 1; padding: 10px; border-radius: 16px; background: #fffdf8; }
.tile { min-width: 0; border: 0; border-radius: 8px; cursor: pointer; transition: transform .12s ease, filter .12s ease; }
.tile:hover { transform: scale(1.06); filter: brightness(1.05); }
.tile:active { transform: scale(.93); }
.tile:focus-visible, button:focus-visible { outline: 3px solid #263238; outline-offset: 3px; }
.coral { --tile: #ed7868; }
.teal { --tile: #55b8a9; }
.gold { --tile: #e8bd58; }
.tile.coral { background: #ed7868; }
.tile.teal { background: #55b8a9; }
.tile.gold { background: #e8bd58; }
.message { min-height: 27px; margin: 16px 0; text-align: center; font-size: 18px; font-weight: 700; color: #41675d; }
.palette { margin: 0; padding: 0; border: 0; text-align: center; }
.palette legend { width: 100%; margin-bottom: 10px; font-size: 17px; font-weight: 650; }
.color-options { display: flex; justify-content: center; gap: 14px; }
.color-button { width: 48px; height: 48px; border: 3px solid #fffdf8; border-radius: 50%; background: var(--tile); cursor: pointer; box-shadow: 0 0 0 1px #cfc6b7; transition: transform .12s, box-shadow .12s; }
.color-button[aria-pressed="true"] { box-shadow: 0 0 0 3px #263238; }
.color-button:hover { transform: translateY(-2px); }
.color-button:active, .reset:active { transform: scale(.96); }
.reset { display: block; margin: 20px auto 0; padding: 11px 18px; border: 1px solid #b9a993; border-radius: 10px; background: #fffdf8; color: #263238; font: inherit; font-size: 16px; font-weight: 650; cursor: pointer; transition: background .12s, transform .12s; }
.reset:hover { background: #eee5d6; }
footer { margin-top: 18px; color: #697476; text-align: center; font-size: 15px; }
@media (max-width: 420px) { .card { padding: 22px 16px; } .game { padding: 16px 12px; } .board { gap: 5px; padding: 8px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const initialGrid = [
  ['coral', 'teal', 'teal', 'gold', 'coral', 'gold'],
  ['coral', 'coral', 'gold', 'gold', 'teal', 'gold'],
  ['teal', 'coral', 'gold', 'teal', 'teal', 'coral'],
  ['gold', 'teal', 'coral', 'coral', 'gold', 'coral'],
  ['gold', 'gold', 'teal', 'coral', 'teal', 'gold'],
  ['coral', 'teal', 'gold', 'teal', 'coral', 'gold']
];
const board = document.querySelector('#board');
const movesDisplay = document.querySelector('#moves');
const message = document.querySelector('#message');
const colorButtons = [...document.querySelectorAll('.color-button')];
let grid;
let selectedColor = 'coral';
let moves = 0;

function render() {
  board.replaceChildren();
  grid.forEach((row, r) => row.forEach((color, c) => {
    const cell = document.createElement('button');
    cell.type = 'button';
    cell.className = `tile ${color}`;
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}, ${color}`);
    cell.addEventListener('click', () => fillFrom(r, c));
    board.append(cell);
  }));
  movesDisplay.textContent = String(moves);
  const uniform = grid.every(row => row.every(color => color === grid[0][0]));
  message.textContent = uniform ? 'One color!' : 'Choose a color, then click a tile.';
}

function fillFrom(row, col) {
  const target = grid[row][col];
  if (target === selectedColor || grid.every(line => line.every(color => color === grid[0][0]))) return;
  const stack = [[row, col]];
  const seen = new Set();
  while (stack.length) {
    const [r, c] = stack.pop();
    const key = `${r},${c}`;
    if (r < 0 || r >= 6 || c < 0 || c >= 6 || seen.has(key) || grid[r][c] !== target) continue;
    seen.add(key);
    grid[r][c] = selectedColor;
    stack.push([r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]);
  }
  moves += 1;
  render();
}

colorButtons.forEach(button => button.addEventListener('click', () => {
  selectedColor = button.dataset.color;
  colorButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
}));
document.querySelector('#reset').addEventListener('click', () => {
  grid = initialGrid.map(row => [...row]);
  moves = 0;
  render();
});
document.addEventListener('DOMContentLoaded', () => {});
grid = initialGrid.map(row => [...row]);
render();
